/// <summary>
/// product category value commitment type for agreement line search
/// </summary>
public class METAgreementLineSearchCommitmentType_ProductCategoryValueCommitment extends METAgreementLineSearchCommitmentType
{
}

Method.Source:
/// <summary>
/// setting range on Category field to exclude 0 (uncategorized)
/// </summary>
/// <param name = "_agreementLineQbds">agreementLineQbds</param>
void agreementLineAddRange(QueryBuildDataSource _agreementLineQbds)
{
    // no filter on itemId as we are using Category
    _agreementLineQbds.addRange(fieldNum(AgreementLine, Category)).value(SysQuery::valueNot(0));
}

/// <summary>
/// getcommitment type
/// </summary>
/// <returns>CommitmentType</returns>
protected CommitmentType getCommitmentType()
{
    return CommitmentType::ProductCategory;
}
